import{c as s,Q as l,j as a,m as n}from"./chunks/framework.DOi4mjdC.js";const i=JSON.parse('{"title":"如何使用掩码操作API","description":"","frontmatter":{},"headers":[{"level":1,"title":"如何使用掩码操作API","slug":"如何使用掩码操作api"}],"relativePath":"guide/编程指南/类库API/基础API/常用操作速查指导/如何使用掩码操作API.md","filePath":"guide/编程指南/类库API/基础API/常用操作速查指导/如何使用掩码操作API.md"}'),o={name:"guide/编程指南/类库API/基础API/常用操作速查指导/如何使用掩码操作API.md"};function e(p,t,g,c,r,d){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="如何使用掩码操作api" tabindex="-1">如何使用掩码操作API <a class="header-anchor" href="#如何使用掩码操作api" aria-label="Permalink to &quot;如何使用掩码操作API&quot;">​</a></h1><p>Mask用于控制矢量计算中参与计算的元素个数，支持以下工作模式及配置方式：</p><p><strong>表 1</strong> Mask工作模式</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.14%&quot;&gt;&lt;p&gt;工作模式&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.86%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.14%&quot;&gt;&lt;p&gt;Normal模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.86%&quot;&gt;&lt;p&gt;默认模式，支持单次迭代内的Mask能力，需要开发者配置迭代次数，额外进行尾块的计算。&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Normal模式下，Mask用来控制单次迭代内参与计算的元素个数。&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;通过调用SetMaskNorm设置Normal模式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.14%&quot;&gt;&lt;p&gt;Counter模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.86%&quot;&gt;&lt;p&gt;简化模式，直接传入计算数据量，&lt;span&gt;自动推断迭代次数，&lt;/span&gt;不需要开发者去感知迭代次数、处理非对齐尾块的操作；但是不具备单次迭代内的Mask能力。&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Counter模式下，Mask表示整个矢量计算参与计算的元素个数。&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;通过调用SetMaskCount设置Counter模式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p><strong>表 2</strong> Mask配置方式</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.12%&quot;&gt;&lt;p&gt;配置方式&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.88%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.12%&quot;&gt;&lt;p&gt;接口传参（默认）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.88%&quot;&gt;&lt;p&gt;&lt;span&gt;通过矢量计算API的入参直接传递Mask值。矢量计算API的&lt;/span&gt;模板参数isSetMask（仅部分API支持）用于控制接口传参还是外部API配置，默认值为true，表示接口传参。&lt;span&gt;Mask对应于高维切分计算API中的mask/mask[]参数或者tensor前n个数据计算API中的calCount参数。&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.12%&quot;&gt;&lt;p&gt;外部API配置&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;85.88%&quot;&gt;&lt;p&gt;&lt;span&gt;调用&lt;/span&gt;SetVectorMask&lt;span&gt;接口设置Mask值，矢量计算API的模板参数isSetMask设置为false，接口入参中的Mask参数（对应于高维切分计算API中的mask/mask[]参数或者tensor前n个数据计算API中的calCount参数）&lt;/span&gt;不生效。适用于Mask参数相同，多次重复使用的场景，无需在矢量计算API内部反复设置，会有一定的性能优势。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>Mask操作的使用方式如下：</p><p><strong>表 3</strong> Mask操作的使用方式</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.58%&quot;&gt;&lt;p&gt;配置方式&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.37%&quot;&gt;&lt;p&gt;工作模式&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;35.67%&quot;&gt;&lt;p&gt;前n个数据计算API&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.38%&quot;&gt;&lt;p&gt;高维切分计算API&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;2&quot; valign=&quot;top&quot; width=&quot;8.58%&quot;&gt;&lt;p&gt;接口传参&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.37%&quot;&gt;&lt;p&gt;Normal模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;35.67%&quot;&gt;&lt;p&gt;不涉及。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.38%&quot;&gt;&lt;p&gt;isSetMask模板参数设置为true，通过接口入参传入Mask，根据使用场景配置&lt;span&gt;dataBlockStride&lt;/span&gt;、&lt;span&gt;repeatStride&lt;/span&gt;&lt;span&gt;、&lt;/span&gt;&lt;span&gt;repeatTime&lt;/span&gt;参数。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Counter模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;isSetMask模板参数设置为true，通过接口入参传入Mask。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;ul&gt;&lt;li&gt;isSetMask模板参数设置为true，通过接口入参传入Mask。&lt;/li&gt;&lt;li&gt;根据使用场景配置&lt;span&gt;dataBlockStride&lt;/span&gt;、&lt;span&gt;repeatStride&lt;/span&gt;参数。&lt;span&gt;repeatTime&lt;/span&gt;传入固定值即可，建议统一设置为1，该值不生效。&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;2&quot; valign=&quot;top&quot; width=&quot;8.58%&quot;&gt;&lt;p&gt;外部API配置&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.37%&quot;&gt;&lt;p&gt;Normal模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;35.67%&quot;&gt;&lt;p&gt;不涉及。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.38%&quot;&gt;&lt;div class=&quot;p&quot;&gt;调用SetVectorMask设置Mask，之后调用高维切分计算API。&lt;ul&gt;&lt;li&gt;isSetMask模板参数设置为false，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。&lt;/li&gt;&lt;li&gt;根据使用场景配置&lt;span&gt;repeatTime&lt;/span&gt;、&lt;span&gt;dataBlockStride&lt;/span&gt;、&lt;span&gt;repeatStride&lt;/span&gt;参数。&lt;/li&gt;&lt;/ul&gt; &lt;/div&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Counter模式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;调用SetVectorMask设置Mask，之后调用前n个数据计算API，isSetMask模板参数设置为false；接口入参中的calCount建议设置成1。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;div class=&quot;p&quot;&gt;调用SetVectorMask设置Mask，之后调用高维切分计算API。&lt;ul&gt;&lt;li&gt;isSetMask模板参数设置为false；接口入参中的mask值设置为MASK_PLACEHOLDER，用于占位，无实际含义。&lt;/li&gt;&lt;li&gt;根据使用场景配置&lt;span&gt;dataBlockStride&lt;/span&gt;、&lt;span&gt;repeatStride&lt;/span&gt;参数。&lt;span&gt;repeatTime&lt;/span&gt;传入固定值即可，建议统一设置为1，该值不生效。&lt;/li&gt;&lt;/ul&gt; &lt;/div&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>典型场景的使用示例如下：</p><ul><li><p>场景1：Normal模式 + 外部API配置 + 高维切分计算API</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src1Local;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 1、设置Normal模式</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>// 2、设置Mask</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::NORMAL&gt;(0xffffffffffffffff, 0xffffffffffffffff);  // 逐bit模式</span></span>
<span class="line"><span>// SetVectorMask&lt;half, MaskMode::NORMAL&gt;(128);</span><span>  // 连续模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 3、多次调用矢量计算API, isSetMask模板参数设置为false，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义</span></span>
<span class="line"><span>// 根据使用场景配置repeatTime、dataBlockStride、repeatStride参数</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::Add&lt;half, false&gt;(dstLocal, src0Local, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Sub&lt;half, false&gt;(src0Local, dstLocal, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Mul&lt;half, false&gt;(src1Local, dstLocal, src0Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>// 4、恢复Mask值为默认值</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span></code></pre></div></li><li><p>场景2：Counter模式 + 外部API配置 + 高维切分计算API</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src1Local;</span></span>
<span class="line"><span>int32_t len = 128;  // 参与计算的元素个数</span></span>
<span class="line"><span>// 1、设置Counter模式</span></span>
<span class="line"><span>AscendC::SetMaskCount();</span></span>
<span class="line"><span>// 2、设置Mask</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::COUNTER&gt;(len);</span></span>
<span class="line"><span>// 3、多次调用矢量计算API, isSetMask模板参数设置为false；接口入参中的mask值设置为MASK_PLACEHOLDER，用于占位，无实际含义</span></span>
<span class="line"><span>// 根据使用场景正确配置dataBlockStride、repeatStride参数。repeatTime传入固定值即可，建议统一设置为1，该值不生效</span></span>
<span class="line"><span>AscendC::Add&lt;half, false&gt;(dstLocal, src0Local, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Sub&lt;half, false&gt;(src0Local, dstLocal, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Mul&lt;half, false&gt;(src1Local, dstLocal, src0Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>// 4、恢复工作模式</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>// 5、恢复Mask值为默认值</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span></code></pre></div></li><li><p>场景3：Counter模式 + 外部API配置 + 前n个数据计算接口配合使用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>half num = 2; </span></span>
<span class="line"><span>// 1、设置Mask</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::COUNTER&gt;(128); // 参与计算的元素个数为128</span></span>
<span class="line"><span>// 2、调用前n个数据计算API，isSetMask模板参数设置为false；接口入参中的calCount建议设置成1。</span></span>
<span class="line"><span>AscendC::Adds&lt;half, false&gt;(dstLocal, src0Local, num, 1);</span></span>
<span class="line"><span>AscendC::Muls&lt;half, false&gt;(dstLocal, src0Local, num, 1);</span></span>
<span class="line"><span>// 3、恢复工作模式</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>// 4、恢复Mask值为默认值</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span></code></pre></div></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>前n个数据计算API接口内部会设置工作模式为Counter模式，所以如果前n个数据计算API配合Counter模式使用时，无需手动调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetMaskCount.md" target="_blank" rel="noreferrer">SetMaskCount</a>设置Counter模式。</li><li>所有手动使用Counter模式的场景，使用完毕后，需要调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetMaskNorm.md" target="_blank" rel="noreferrer">SetMaskNorm</a>恢复工作模式。</li><li>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetVectorMask.md" target="_blank" rel="noreferrer">SetVectorMask</a>设置Mask，使用完毕后，需要调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/ResetMask.md" target="_blank" rel="noreferrer">ResetMask</a>恢复Mask值为默认值。</li><li>使用高维切分计算API配套Counter模式使用时，比前n个数据计算API增加了可间隔的计算，支持dataBlockStride、repeatStride参数。</li></ul></div>`,12)])])}const q=s(o,[["render",e]]);export{i as __pageData,q as default};
